  function renderLoop(){renderFrame();if(state.playing){const c=clip();if(c&&c.type==='image'){const now=performance.now();if(!state.lastImageTick)state.lastImageTick=now;const dt=(now-state.lastImageTick)/1000;state.lastImageTick=now;state.currentTime+=dt*(c.settings.speed||1);if(state.currentTime>=(c.end??c.duration)){state.currentTime=c.end??c.duration;stopPlayback();}}else if(c&&video.readyState>=2){state.currentTime=video.currentTime;if(state.currentTime>=(c.end??video.duration)-.015){state.currentTime=c.end??video.duration;stopPlayback();}}}state.raf=requestAnimationFrame(renderLoop);}
