    const c=clip();if(c&&(c.settings.text||c.settings.sticker||c.settings.overlay||c.settings.captions?.length)){const el=document.createElement('div');el.className='clip-block';el.style.background='#654627';el.style.borderColor='#a27743';el.style.width=`${Math.max(80,durationOf(c)*scale)}px`;el.innerHTML=`<small>✦</small><span>${esc(c.settings.text||c.settings.sticker||'Text / overlay')}</span>`;ot.append(el);}else ot.innerHTML='<div class="clip-empty">Text, stickers and overlays appear here</div>';
