  function rangeControl(label,key,min,max,step,suffix='',scale=1){const s=settings();return `<div class="control-row"><label>${label}</label><output id="out-${key}">${Number((s?.[key]??0))*scale}${suffix}</output></div><input class="range-control" data-setting="${key}" data-scale="${scale}" data-suffix="${suffix}" type="range" min="${min}" max="${max}" step="${step}" value="${s?.[key]??0}">`;}
