  $('#collapsePanelBtn').addEventListener('click',()=>$('#assetPanel').classList.remove('open'));$('#profileBtn').textContent=(state.profile[0]||'G').toUpperCase();$('#profileBtn').addEventListener('click',showProfile);
  $('#playBtn').addEventListener('click',playPause);$('#scrubSlider').addEventListener('input',e=>{state.isFrozen=false;setCurrentTime(Number(e.target.value));});$('#backFrameBtn').addEventListener('click',()=>setCurrentTime(state.currentTime-1));$('#forwardFrameBtn').addEventListener('click',()=>setCurrentTime(state.currentTime+1));
