  $('#undoBtn').addEventListener('click',undo);$('#redoBtn').addEventListener('click',redo);$('#timelineZoomIn').addEventListener('click',()=>{state.timelineZoom=clamp(state.timelineZoom*1.2,.5,4);renderTimeline();});$('#timelineZoomOut').addEventListener('click',()=>{state.timelineZoom=clamp(state.timelineZoom/1.2,.5,4);renderTimeline();});$('#fitPreviewBtn').addEventListener('click',()=>{resetRatio();$('#zoomLabel').textContent='Fit';});
  $('#saveProjectBtn').addEventListener('click',saveProject);$('#openProjectsBtn').addEventListener('click',openProjects);$('#newProjectBtn').addEventListener('click',startNewProject);$('#exportVideoBtn').addEventListener('click',showExportDialog);$('#exportProjectBtn').addEventListener('click',()=>showModal('Export project data','Export the timeline metadata for archival or another workflow.','<div class="settings-info">XML and JSON exports contain clip metadata, effects, trim points and project settings. They do not embed the original video/image files and are not a rendered video.</div>',[modalButton('Cancel','ghost',closeModal),modalButton('Export XML','primary',()=>{exportXML();closeModal();}),modalButton('Export JSON','ghost',()=>{exportJSON();closeModal();})]));
  $('#resetSettingsBtn').addEventListener('click',()=>{const c=clip();if(!c)return;pushHistory();c.settings=defaults();renderInspector();renderFrame();toast('Clip adjustments reset');});$('#modalCloseBtn').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop')&&!state.exporting)closeModal();});
  document.addEventListener('keydown',e=>{const target=e.target,typing=target&&(['INPUT','TEXTAREA','SELECT'].includes(target.tagName)||target.isContentEditable);if(e.key==='Escape'&&!state.exporting)closeModal();if(!typing&&e.code==='Space'){e.preventDefault();playPause();}if(!typing&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if(!typing&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();}if(!typing&&e.key==='Delete'&&clip())deleteClip();});
